# Chart

Displays information in a visual way.

## Introduction

## Usage

### Bar Chart

```ruby
options = {
  type: 'bar',
  data: {
    labels: ['Phlex', 'VC', 'ERB'],
    datasets: [{
      label: 'render time (ms)',
      data: [100, 520, 1200],
    }]
  },
  options: {
    indexAxis: 'y',
    scales: {
      y: {
        beginAtZero: true
      }
    },
  },
}

Chart(options: options)
```

### Multiple datasets

```ruby
options = {
  type: 'bar',
  data: {
    labels: ['January', 'February', 'March', 'April', 'May', 'June'],
    datasets: [
      { label: 'Desktop', data: [186, 305, 237, 73, 209, 214] },
      { label: 'Mobile', data: [80, 200, 120, 190, 130, 140] }
    ]
  },
}

Chart(options: options)
```

### Line Graph

```ruby
options = {
  type: 'line',
  data: {
    labels: ['Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul'],
    datasets: [{
      label: 'Github Stars',
      data: [40, 30, 79, 140, 290, 550],
    }]
  },
  options: {
    scales: {
      y: {
        beginAtZero: true
      }
    },
    plugins: {
      legend: {
        display: false
      }
    }
  },
}

Chart(options: options)
```

### Pie Chart

```ruby
options = {
  type: 'pie',
  data: {
    labels: [
      'Red',
      'Blue',
      'Yellow'
    ],
    datasets: [{
      label: 'My First Dataset',
      data: [300, 50, 100],
      backgroundColor: [
        'rgb(255, 99, 132)',
        'rgb(54, 162, 235)',
        'rgb(255, 205, 86)'
      ],
      hoverOffset: 4
    }]
  },
}

Chart(options: options)
```

